import{_ as a,a as t,c as s,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 102 He says he ...","description":"学习 间接引语中的人称转换，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 102 He says he ...","description":"学习 间接引语中的人称转换，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 间接引语中的人称转换，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 101 A card from Jimmy","link":"/life/english/new-concept/book-1/unit-05/lesson-101"},"next":{"text":"第一册：英语初阶 · Lesson 103 The French test","link":"/life/english/new-concept/book-1/unit-05/lesson-103"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 101 A card from Jimmy","link":"/life/english/new-concept/book-1/unit-05/lesson-101"},"next":{"text":"第一册：英语初阶 · Lesson 103 The French test","link":"/life/english/new-concept/book-1/unit-05/lesson-103"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-102.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-102.md"}'),i={name:"life/english/new-concept/book-1/unit-05/lesson-102.md"};function n(r,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-102-he-says-he" tabindex="-1">第一册：英语初阶 · Lesson 102 He says he ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-102-he-says-he" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 102 He says he ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-101">配套课 Lesson 101</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>转述信件内容并调整人称 本课要掌握间接引语中的人称转换，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>card</td><td>/kɑːd/</td><td>n.</td><td>明信片；卡片</td><td>send a card</td></tr><tr><td>hostel</td><td>/ˈhɒstl/</td><td>n.</td><td>旅舍</td><td>stay in a hostel</td></tr><tr><td>arrive</td><td>/əˈraɪv/</td><td>v.</td><td>到达</td><td>arrive safely</td></tr><tr><td>message</td><td>/ˈmesɪdʒ/</td><td>n.</td><td>信息</td><td>read a message</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>send a card — 寄明信片</li><li>says she is — 人称转换后的引述</li></ul><h2 id="语法讲解-间接引语中的人称转换" tabindex="-1">语法讲解：间接引语中的人称转换 <a class="header-anchor" href="#语法讲解-间接引语中的人称转换" aria-label="Permalink to &quot;语法讲解：间接引语中的人称转换&quot;">​</a></h2><p>把别人第一人称的话转述出来时，应按实际身份转换 I、my、we 等代词，而不是固定一律变 he。主句 says 为现在时，从句可保留原来的时态；说话者的 I 如果指 Rita，转述可用 she。时间地点词是否改变取决于转述发生的时间和地点，不是见到间接引语就机械替换全部词。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The boys say they will arrive tomorrow.</p></blockquote><p>男孩们说他们明天到达。</p><p>The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>转述 Rita 的 my aunt 通常要变 her aunt，而不是保留成转述者的 my。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“The boys say they will arrive tomorrow.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The boys say they will arrive tomorrow. Rita says she is staying with her aunt.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“转述信件内容并调整人称”写两至三句，再读给同伴听。至少使用一次间接引语中的人称转换，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。 Rita says 是现在时引述；she 与 her 都指 Rita，is staying 描述她现阶段的居住安排。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>The boys say, &quot;We will arrive.&quot; 改为间接引语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The boys say they will arrive.</p><p><strong>解析：</strong> 按本课规则判断：把别人第一人称的话转述出来时，应按实际身份转换 I、my、we 等代词，而不是固定一律变 he。主句 says 为现在时，从句可保留原来的时态；说话者的 I 如果指 Rita，转述可用 she。时间地点词是否改变取决于转述发生的时间和地点，不是见到间接引语就机械替换全部词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“男孩们说他们明天到达。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The boys say they will arrive tomorrow.</p><p><strong>解析：</strong> The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Rita says she is staying with her aunt.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 丽塔说她正和姨妈住在一起。</p><p><strong>解析：</strong> Rita says 是现在时引述；she 与 her 都指 Rita，is staying 描述她现阶段的居住安排。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接引语中的人称转换。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-101">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-103">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",n]]);export{u as __pageData,b as default};
